def decode_list(alist):
    """Write a function to decode a run-length encoded given list.

    Elements that are ``[count, value]`` pairs (a list or tuple of
    length two whose first element is an integer count) are expanded
    to ``count`` copies of ``value``. All other elements are copied
    through unchanged.
    """
    decoded = []
    for item in alist:
        if (
            isinstance(item, (list, tuple))
            and len(item) == 2
            and isinstance(item[0], int)
            and not isinstance(item[0], bool)
        ):
            count, value = item
            decoded.extend([value] * count)
        else:
            decoded.append(item)
    return decoded
